// ════════════════════════════════════════════════════════════════
// Glossaire statique FR → ES (mode « Español »).
//
// Même rôle que UI_GLOSSARY (glossary.js) pour l'anglais : le vocabulaire
// d'interface le plus fréquent bascule instantanément, hors ligne et sans
// appel IA. Le reste (recettes, étapes, notes…) part à l'IA puis au cache.
//
// MÊMES CLÉS que UI_GLOSSARY, dans le même ordre : toute entrée ajoutée au
// glossaire anglais doit l'être ici aussi. `npm run lint:glossary` le vérifie.
//
// Registre : espagnol de cuisine professionnelle (castillan), compréhensible
// par un cuisinier latino-américain. Actions à l'infinitif (« Guardar »),
// tutoiement quand le texte s'adresse à l'utilisateur. Vocabulaire métier
// aligné sur la tâche `translate` d'ai-proxy : carte → carta, perte → merma,
// pointage → fichaje, dressage → emplatado, portion → ración.
// ════════════════════════════════════════════════════════════════

