  'Ces chiffres sont réservés à la direction et aux personnes qui règlent les factures. Demandez à votre consultant le droit « Régler les factures ».': 'Estas cifras están reservadas a la dirección y a quienes pagan las facturas. Pida a su consultor el derecho «Pagar facturas».',
  "La comptabilité n'est pas encore activée sur la base de données.": 'La contabilidad aún no está activada en la base de datos.',
  "Les achats et les marges se lisent déjà ; la saisie du chiffre d'affaires, les charges fixes, les salaires et la banque arriveront avec elle.": 'Las compras y los márgenes ya se pueden leer; la entrada de la facturación, los gastos fijos, los salarios y el banco llegarán con ella.',
  "La comptabilité de l'app prépare vos chiffres et vos pièces pour la fiduciaire. Elle ne tient pas les comptes et n'établit ni le décompte TVA officiel ni les salaires.": 'La contabilidad de la app prepara sus cifras y justificantes para la gestoría. No lleva la contabilidad ni elabora la declaración oficial del IVA ni las nóminas.',
  "Aucun inventaire validé : la période d'inventaire commence au premier inventaire validé.": 'Ningún inventario validado: el período de inventario empieza con el primer inventario validado.',
  'Montants TVA comprise, comme sur le ticket de caisse du soir.': 'Importes con IVA incluido, como en el ticket de caja de la noche.',
  'La caisse a enregistré': 'La caja registró',
  'ce jour-là. Une saisie ici la remplace pour ce jour.': 'ese día. Una entrada aquí la sustituye para ese día.',
  "Seule une personne qui règle les factures peut saisir le chiffre d'affaires.": 'Solo una persona que paga las facturas puede introducir la facturación.',
  "Une charge fixe se saisit une fois : l'app la répartit sur chaque mois. N'importez pas aussi sa facture dans Factures & achats, sinon elle compte deux fois.": 'Un gasto fijo se introduce una vez: la app lo reparte en cada mes. No importe también su factura en Facturas y compras, o contará dos veces.',
