  "Les heures de relevé ne sont pas les mêmes d'une maison à l'autre : un seul service qui démarre à 6h ne se relève pas comme un double service midi et soir. Réglez ici les heures de l'établissement : la carte de l'accueil HACCP dit à l'équipe quand relever, et le tableau de bord signale un relevé en retard. Un relevé en dehors de ces heures reste toujours possible.": 'Las horas de registro no son las mismas de una casa a otra: un solo servicio que empieza a las 6 no se registra como un doble servicio de mediodía y noche. Fije aquí las horas del establecimiento: la tarjeta de la portada HACCP le dice al equipo cuándo registrar, y el panel señala un registro con retraso. Un registro fuera de estas horas siempre es posible.',
