  'Taux de TVA par catégorie': 'Tipo de IVA por categoría',
  "Sur place, le taux de la catégorie s'applique. Quand un ticket est marqué à emporter, seules les catégories cochées passent au taux réduit ; l'alcool reste toujours au taux normal. Le taux est figé sur chaque ligne à l'encaissement.": 'En el local se aplica el tipo de la categoría. Cuando un ticket se marca para llevar, solo las categorías marcadas pasan al tipo reducido; el alcohol queda siempre al tipo normal. El tipo queda fijado en cada línea al cobrar.',
  'Taux réduit à emporter': 'Tipo reducido para llevar',
