  // Caisse v9 : terminal de paiement relié.
  'Terminal de paiement': 'Terminal de pago',
  'Au tap sur « Carte », la caisse envoie le montant au terminal ; le client paie sur le terminal ; la caisse reçoit « accepté » ou « refusé » et pose le paiement toute seule.': 'Al tocar «Tarjeta», la caja envía el importe al terminal; el cliente paga en el terminal; la caja recibe «aceptado» o «rechazado» y anota el pago sola.',
  "La caisse ne voit jamais une carte : ni numéro, ni date, ni code. Elle garde seulement le résultat (marque, quatre derniers chiffres, code d'autorisation). L'argent va du prestataire à la maison, sans passer par l'app.": 'La caja nunca ve una tarjeta: ni número, ni fecha, ni código. Solo guarda el resultado (marca, cuatro últimas cifras, código de autorización). El dinero va del proveedor a la casa, sin pasar por la app.',
  'Terminaux reliés': 'Terminales vinculados',
  "Les terminaux n'ont pas pu être lus. Fermez les Réglages et rouvrez-les.": 'No se han podido leer los terminales. Cierre los Ajustes y vuelva a abrirlos.',
  "Aucun terminal relié : les cartes s'encaissent à la main, comme aujourd'hui.": 'Ningún terminal vinculado: las tarjetas se cobran a mano, como hoy.',
  'Terminal simulé': 'Terminal simulado',
  'n° de série': 'n.º de serie',
  'Clé enregistrée, se termine par': 'Clave guardada, termina en',
  'Clé enregistrée': 'Clave guardada',
  'Relié le': 'Vinculado el',
  'Il ne sert que les tickets du mode test : aucun argent ne bouge, aucun vrai ticket ne peut être payé par lui.': 'Solo sirve para los tickets del modo de prueba: no se mueve dinero y ningún ticket real puede pagarse con él.',
  'Ce terminal a déjà encaissé un paiement réel accepté.': 'Este terminal ya ha cobrado un pago real aceptado.',
  "Ce terminal n'a pas encore encaissé de paiement réel accepté : faites un premier paiement de 1 franc avant le service.": 'Este terminal aún no ha cobrado ningún pago real aceptado: haga un primer pago de 1 franco antes del servicio.',
  'Garder': 'Conservar',
  'Retirer ce terminal': 'Retirar este terminal',
  'Terminaux retirés :': 'Terminales retirados:',
  'Leurs paiements passés restent dans la caisse ; un remboursement se fait alors chez le prestataire.': 'Sus pagos anteriores permanecen en la caja; un reembolso se hace entonces con el proveedor.',
  'Relier un terminal': 'Vincular un terminal',
  'Prestataire': 'Proveedor',
  'Clé': 'Clave',
  'Jumelage': 'Emparejamiento',
  "Aucun prestataire réel n'est encore proposé. Le terminal simulé sert à s'entraîner en mode test ; un vrai terminal sera ajouté quand son prestataire aura confirmé ses règles et fourni un moyen d'essai sans argent réel.": 'Aún no se ofrece ningún proveedor real. El terminal simulado sirve para practicar en modo de prueba; se añadirá un terminal real cuando su proveedor haya confirmado sus reglas y facilitado una forma de probar sin dinero real.',
  "Nom du terminal, tel que l'équipe le verra": 'Nombre del terminal, tal como lo verá el equipo',
  'Terminal du bar': 'Terminal de la barra',
  'Numéro de série, lu sous le terminal': 'Número de serie, leído bajo el terminal',
  'Saisie masquée': 'Entrada oculta',
  "La clé part une seule fois vers le serveur, qui la range dans son coffre. Elle ne revient jamais à l'écran : seuls ses quatre derniers caractères seront rappelés.": 'La clave se envía una sola vez al servidor, que la guarda en su caja fuerte. Nunca vuelve a la pantalla: solo se recordarán sus cuatro últimos caracteres.',
  'Code de jumelage': 'Código de emparejamiento',
  'Code lu sur le terminal': 'Código leído en el terminal',
  "Le code s'affiche sur le terminal et ne sert qu'une fois : il prouve que le terminal est devant vous.": 'El código aparece en el terminal y solo sirve una vez: demuestra que el terminal está delante de usted.',
  'Relier ce terminal': 'Vincular este terminal',
  'Relier ou retirer un terminal : consultant ou patron de la maison.': 'Vincular o retirar un terminal: consultor o propietario de la casa.',
  "Plafond d'un paiement sur le terminal, en CHF": 'Límite de un pago en el terminal, en CHF',
  "Au-dessus de ce montant, pourboire compris, la caisse n'envoie rien au terminal : une erreur de saisie ne part pas en débit.": 'Por encima de este importe, propina incluida, la caja no envía nada al terminal: un error de tecleo no se convierte en cargo.',
