  'Couverts des réservations honorées, non pointées et prévues ; ni les annulées ni les no-show.': 'Cubiertos de las reservas cumplidas, sin registrar y previstas; ni las canceladas ni los no presentados.',
  'Réservations valides, annulées exclues. Une table est une réservation, pas une table de la salle.': 'Reservas válidas, canceladas excluidas. Una mesa es una reserva, no una mesa de la sala.',
