  "Montant des factures d'achat non exclues : total hors TVA, à défaut TVA comprise, à défaut somme des lignes lues. Jour de la date de facture.": 'Importe de las facturas de compra no excluidas: total sin IVA, en su defecto con IVA, en su defecto suma de las líneas leídas. Día de la fecha de factura.',
