  "Chiffre du jour saisi ou clôturé par la caisse, à défaut ventes de la caisse reliée, plus les notes de séjour d'un hôtel.": 'Cifra del día introducida o cerrada por la caja, en su defecto ventas de la caja conectada, más las notas de estancia de un hotel.',
  "Ventes moins la TVA, calculée sur le total de chaque taux : la somme des points peut s'écarter du total de quelques centimes.": 'Ventas menos el IVA, calculado sobre el total de cada tipo: la suma de los puntos puede diferir del total en unos céntimos.',
  'Achats hors TVA de la période, par date de facture, avec la règle des Analyses des dépenses.': 'Compras sin IVA del periodo, por fecha de factura, con la regla de los Análisis de gastos.',
